import React, { useEffect, useState } from 'react';
import { invoke } from '@forge/bridge';

function App() {
    const [data, setData] = useState(null);

    useEffect(() => {
        invoke('getText', { example: 'my-invoke-variable' }).then(setData);
    }, []);

    return (
        <div>
            <h1>GIM-HORIZON 2026</h1>
            <div>
                {data ? data : 'Loading...'}
            </div>
        </div>
    );
}

export default App;
